mapper.select:
SELECT COUNT(*)
FROM dieta_alimento
WHERE id_alimento = #{idAlimento};

mapper.insert:
INSERT INTO alimento (
    nombre,
    porcion,
    calorias_por_porcion,
    id_unidad_porcion
) VALUES (
    #{nombre},
    #{porcion},
    #{caloriasPorPorcion},
    #{idUnidadPorcion}
);

mapper.update:
UPDATE alimento
SET
    nombre = #{nombre},
    porcion = #{porcion},
    calorias_por_porcion = #{caloriasPorPorcion}
WHERE id_alimento = #{idAlimento};
